using GameTranslator.Core;
namespace GameTranslator.Core.Tests;
public class ReadingAreaTests_056
{
    private static PanelCell Cell(string text,double top,string background="#F8F8F8")=>new(text,"",new(.1,top,.8,top+.05),background,"#20232A",.025,true);
    private static PanelLayout Page(params PanelCell[] cells)=>new(400,700,"phone",null,cells);
    [Fact]public void PartialPhoneReadDoesNotDeleteKnownMessagesOrJitterColour(){var tracker=new PhonePanelTracker();var a=Cell("First complete message.",.2);var b=Cell("Second complete message.",.4);var c=Cell("Third complete message.",.6);tracker.Observe(Page(a,b,c),0);var changed=tracker.Observe(Page(a with{Background="#EEE0DD",Box=a.Box with{Top=.205}},c),300)!;Assert.Equal(3,changed.Cells.Count);Assert.Equal(a.Background,changed.Cells[0].Background);Assert.Equal(a.Box,changed.Cells[0].Box);Assert.Contains(changed.Cells,x=>x.Source==b.Source);}
    [Fact]public void ScrollingToAnotherPageRequiresConfirmationAndRemovesOldText(){var t=new PhonePanelTracker();t.Observe(Page(Cell("This is the old message.",.2)),0);var next=Page(Cell("A completely different message.",.2));Assert.Contains("old",t.Observe(next,200)!.Cells[0].Source);Assert.Contains("different",t.Observe(next,400)!.Cells[0].Source);}
    [Fact]public void SenderNamesAloneCannotPaintAWhitePhonePage(){var t=new PhonePanelTracker();Assert.Null(t.Observe(Page(Cell("Santiago",.2),Cell("Jason, Lucia",.4)),0));}
    [Fact]public void UnstableNewPageCannotKeepTheOldChatAliveForever(){var t=new PhonePanelTracker();t.Observe(Page(Cell("This is the old message.",.2)),0);t.Observe(Page(Cell("A completely different message.",.2)),100);Assert.Null(t.Observe(Page(Cell("Another changing message.",.2)),800));}
    [Fact]public void TiltedLineUsesWordHeightAndManualSizeRemainsIndependent(){var f=Frame.Blank(400,700);var p=SpatialText.Build(f,new([new("A long tilted message.",new(.1,.2,.8,.32),LineHeight:.025)]),ReadingAreaKind.Phone);Assert.Equal(.025,p.Cells[0].LineHeight);var manual=SpatialText.ReflowPhone(p,18);Assert.Equal(18,manual.Cells[0].LineHeight*manual.Height,1);}
    [Fact]public async Task TaskCardCannotRepeatTheDialogueWithItsOwnAccent(){var frame=Frame.Blank(400,700);var dialogue=new SubtitlePipeline(new LinesReader(new([new("Karim: I am not going to explain it.",new(.1,.8,.9,.95))])),new FakeTranslator(),new FakeSender());await dialogue.ProcessAsync(frame,new(0,1,0,1));var engine=new FakeTranslator();using var s=new ReadingAreaSession([ReadingArea.Instructions() with{Source=new(0,1,0,1)}],()=>new LinesReader(new([new("I am not going to explain it.",new(.1,.88,.9,.95))])),engine,isDialogue:dialogue.IsDialogueFragment);await s.ProcessAsync(frame);Assert.Empty(engine.Requested);Assert.True(dialogue.IsDialogueFragment("I am not going to explain it.",new(.1,.88,.9,.95)));Assert.False(dialogue.IsDialogueFragment("I am not going to explain it.",new(.1,.1,.9,.2)));}
    [Theory][InlineData("You son of a bitch!","يا ابن القحبة!","يا ابن العاهرة!")][InlineData("Let's go!","يلا، هذي فرصتنا.","هيا، هذه فرصتنا.")]
    public void FormalArabicKeepsMeaningAndExplicitLanguage(string source,string text,string expected){Assert.Equal(expected,ArabicRegister.Normalize(text));Assert.False(ArabicRegister.NeedsRephrase(source,expected));}
    [Fact]public void AmbiguousDialectNeedsSourceRetranslationButNamesAreNotBlanketReplaced(){Assert.True(ArabicRegister.NeedsRephrase("What do you want?","وش تبغى؟"));Assert.True(ArabicRegister.NeedsRephrase("What he said.","اللي قاله."));Assert.False(ArabicRegister.NeedsRephrase("Hey Mo!","مرحبًا يا مو!"));Assert.Equal("راح خالد إلى المتجر.",ArabicRegister.Normalize("راح خالد إلى المتجر."));}
}
